SELECT ho.hotel_ID, ho.hotelName, ho.phoneNumber, ho.email, ad.country, ad.city, ad.district, ad.streetAddress
FROM hotel ho
INNER JOIN [address] ad ON ho.address_ID = ad.address_ID;

subSql.sql:
DELETE FROM roomCategory_equipment
WHERE roomCategory_ID = @roomCategory_ID
	AND equipment_ID = @equipment_ID;

DELETE FROM room
WHERE hotel_ID = @hotel_ID
	AND roomNumber = @roomNumber;

SELECT hotel_ID, additionalOptionTitle AS title, CONCAT(price, '€') AS price
FROM additionalOption
WHERE hotel_ID = @hotel_ID;

DELETE FROM additionalOption
WHERE additionalOptionTitle = @title
	AND hotel_ID = @hotel_ID;
